     * unbound from any statement figure); their name and aliases become the other's aliases; their patrons are added
     * to the other's and anyone naming them as patron names the other instead (never the other themselves, no
     * repeats); their pool memberships move to the other (shares added where the other is a member already) and their
     * closed periods' totals add to the other's. Their statements, holds, watchers, grades and contact are dropped
     * with them. False (nothing written) when either was saved by someone else in the meantime.
     */
    public boolean merge(Person from, Person into) {
        String sheetId = from.getSheetId();
        long f = from.getId();
        long t = into.getId();
        if (jdbc.update("UPDATE person SET version = version + 1 WHERE id = ? AND version = ?", t, into.getVersion()) == 0
                || jdbc.update("UPDATE person SET version = version + 1 WHERE id = ? AND version = ?", f,
                        from.getVersion()) == 0) {
            return false;
        }
        for (Long claimId : jdbc.queryForList("SELECT id FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id",
                Long.class, sheetId, f)) {
            Long listed = jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE "
                    + "(UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)", Long.class, sheetId);
            jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, listed = ? WHERE id = ?", t,
                    listed, claimId);
        }
        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?", t, sheetId, f);
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", sheetId, t,
                from.getName());
        jdbc.update("INSERT INTO person_patron (person_id, patron_id) SELECT ?, pp.patron_id FROM person_patron pp"
                + " WHERE pp.person_id = ? AND pp.patron_id <> ? AND NOT EXISTS"
                + " (SELECT 1 FROM person_patron o WHERE o.person_id = ? AND o.patron_id = pp.patron_id)"
                + " ORDER BY pp.named", t, f, t, t);
        jdbc.update("INSERT INTO person_patron (person_id, patron_id, named) SELECT pp.person_id, ?, pp.named FROM person_patron pp"
                + " WHERE pp.patron_id = ? AND pp.person_id <> ? AND NOT EXISTS"
                + " (SELECT 1 FROM person_patron o WHERE o.person_id = pp.person_id AND o.patron_id = ?)", t, f, t, t);
        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", f, f);
        jdbc.update("UPDATE pool_member m SET share = share + (SELECT o.share FROM pool_member o WHERE o.pool_id = m.pool_id"
                + " AND o.person_id = ?) WHERE m.person_id = ? AND EXISTS (SELECT 1 FROM pool_member o"
                + " WHERE o.pool_id = m.pool_id AND o.person_id = ?)", f, t, f);
        jdbc.update("DELETE FROM pool_member m WHERE m.person_id = ? AND EXISTS (SELECT 1 FROM pool_member o"
                + " WHERE o.pool_id = m.pool_id AND o.person_id = ?)", f, t);
        jdbc.update("UPDATE pool_member SET person_id = ? WHERE person_id = ?", t, f);
        jdbc.update("UPDATE period_person_total m SET total = total + (SELECT o.total FROM period_person_total o"
                + " WHERE o.period_id = m.period_id AND o.person_id = ?) WHERE m.person_id = ? AND EXISTS"
                + " (SELECT 1 FROM period_person_total o WHERE o.period_id = m.period_id AND o.person_id = ?)", f, t, f);
        jdbc.update("DELETE FROM period_person_total m WHERE m.person_id = ? AND EXISTS (SELECT 1 FROM period_person_total o"
                + " WHERE o.period_id = m.period_id AND o.person_id = ?)", f, t);
        jdbc.update("UPDATE period_person_total SET person_id = ? WHERE person_id = ?", t, f);
        jdbc.update("DELETE FROM statement WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person WHERE id = ?", f);
        return true;
    }

    /** Move the person to the next version; false (nothing written) when someone else saved them in the meantime. */
    public boolean touch(Person person) {
        if (jdbc.update("UPDATE person SET version = version + 1 WHERE id = ? AND version = ?", person.getId(),
                person.getVersion()) == 0) {
            return false;
        }
        person.setVersion(person.getVersion() + 1);
        return true;
    }

    /**
     * Transfer the person to the other sheet (stored already): they are added there with their name, terms, contact,
     * every grade they were given (with its from-date) and their aliases, noting this sheet as the one they came from; their claims move with them (status, dates,
     * notes, settled figures, logs and comments kept), listed there in the order they were listed here, each unbound
     * from any statement figure, without its reference or settle batch, and numbered by {@code numbers} (by claim id;
     * a claim absent keeps no number), a correction or split naming its claim by the new number; their tags are noted
     * as used there. Everything else of theirs here — patron links either way, pool memberships, watches, holds,
     * statements and closed periods' totals — is dropped with them. Answers the person's id on the other sheet.
     */
    public long transfer(Person from, String toSheet, Map<Long, String> numbers) {
        long f = from.getId();
        String grade = from.getGrade() != null ? from.getGrade() : from.getGrades().get(0).grade();
        long t = insert(toSheet, from.getName(), grade, from.getTerms(), from.getContact()).getId();
        jdbc.update("UPDATE person SET origin = ? WHERE id = ?", from.getSheetId(), t);
        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", t);
        jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) SELECT ?, grade, from_date FROM person_grade"
                + " WHERE person_id = ?", t, f);
        jdbc.update("UPDATE person_alias SET sheet_id = ?, person_id = ? WHERE person_id = ?", toSheet, t, f);
        moveClaims(from, toSheet, t, numbers);
        dropRest(f);
        return t;
    }

    /**
     * Transfer the person to the other sheet merging them into a person there ({@code into}, still at the version they
     * were loaded at), as {@link #merge} does: their claims move to the other as {@link #transfer} moves them, listed
     * after the other's claims; their name and aliases become the other's aliases; everything else of theirs is
     * dropped with them (grades, terms and contact too). False (nothing written) when the other was saved by someone
     * else in the meantime.
     */
    public boolean transferInto(Person from, Person into, Map<Long, String> numbers) {
        long f = from.getId();
        long t = into.getId();
        String toSheet = into.getSheetId();
        if (jdbc.update("UPDATE person SET version = version + 1 WHERE id = ? AND version = ?", t,
                into.getVersion()) == 0) {
            return false;
        }
        jdbc.update("UPDATE person_alias SET sheet_id = ?, person_id = ? WHERE person_id = ?", toSheet, t, f);
        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) VALUES (?, ?, ?)", toSheet, t,
                from.getName());
        moveClaims(from, toSheet, t, numbers);
        dropRest(f);
        return true;
    }

    /** Move the person's claims to the other sheet's person {@code t}, as {@link #transfer} describes. */
    private void moveClaims(Person from, String toSheet, long t, Map<Long, String> numbers) {
        long f = from.getId();
        List<Map<String, Object>> claims = jdbc.queryForList(
                "SELECT id, claim_number, corrects, split_from, tags FROM claim WHERE person_id = ? ORDER BY listed", f);
        Map<String, String> renumbered = new java.util.HashMap<>();
        for (Map<String, Object> claim : claims) {
            if (claim.get("claim_number") != null) {
                renumbered.put((String) claim.get("claim_number"), numbers.get(((Number) claim.get("id")).longValue()));
            }
        }
        for (Map<String, Object> claim : claims) {
            long id = ((Number) claim.get("id")).longValue();
            Long listed = jdbc.queryForObject("SELECT last_claim_listed FROM FINAL TABLE "
                    + "(UPDATE sheet SET last_claim_listed = last_claim_listed + 1 WHERE id = ?)", Long.class, toSheet);
            jdbc.update("UPDATE claim SET sheet_id = ?, person_id = ?, listed = ?, claim_number = ?, corrects = ?,"
                    + " split_from = ?, stated = FALSE, stated_due = NULL, ref = NULL, settle_batch = NULL WHERE id = ?",
                    toSheet, t, listed, numbers.get(id), renumbered.get((String) claim.get("corrects")),
                    renumbered.get((String) claim.get("split_from")), id);
            jdbc.update("UPDATE claim_log SET sheet_id = ? WHERE claim_id = ?", toSheet, id);
            jdbc.update("UPDATE claim_comment SET sheet_id = ? WHERE claim_id = ?", toSheet, id);
            jdbc.update("DELETE FROM claim_lock WHERE claim_id = ?", id);
            String tags = (String) claim.get("tags");
            if (tags != null) {
                for (String tag : tags.split(",")) {
                    jdbc.update("MERGE INTO claim_tag (sheet_id, tag) KEY (sheet_id, tag) VALUES (?, ?)", toSheet, tag);
                }
            }
        }
    }

    /** Drop everything else of the person's here, and the person. */
    private void dropRest(long f) {
        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", f, f);
        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_retirement WHERE person_id = ?", f);
        jdbc.update("DELETE FROM statement WHERE person_id = ?", f);
        jdbc.update("DELETE FROM period_person_total WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person_grade WHERE person_id = ?", f);
        jdbc.update("DELETE FROM person WHERE id = ?", f);
    }

    /** Sets each person's patrons' names, in the order named, their grades, their holds and their past retirements. */
    private List<Person> withPatrons(String sheetId, List<Person> people) {
package net.officefloor.hq.app.sheet;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * Copies a sheet to a sheet id never used: its today, settings, roles, rates, holidays, void reasons, templates, the
 * tags ever used on its claims, its people (grades, terms, contacts, aliases, holds, retirements, patrons), its pools,
 * its periods (all open, with no figures fixed) and its claims (status, frozen figures, dates, notes, logs). Its
 * statements are not copied (no claim is bound), nor its snapshots, watches, delegations, comments, editor locks or
 * settle batches.
 */
@Repository
public class SheetCloneRepository {

    private final JdbcTemplate jdbc;

    public SheetCloneRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Create the clone with everything but its claims; answers the clone's person id for each person's id. */
    public Map<Long, Long> copySheet(String from, String to) {
        jdbc.update("INSERT INTO sheet (id, today, last_claim_listed) SELECT ?, today, last_claim_listed FROM sheet"
                + " WHERE id = ?", to, from);
        jdbc.update("INSERT INTO sheet_setting (sheet_id, setting_key, setting_value) SELECT ?, setting_key,"
                + " setting_value FROM sheet_setting WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO sheet_setting_from (sheet_id, setting_key, from_date, setting_value) SELECT ?,"
                + " setting_key, from_date, setting_value FROM sheet_setting_from WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO sheet_role (sheet_id, user_name, role) SELECT ?, user_name, role FROM sheet_role"
                + " WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO rate (sheet_id, grade, rate, from_date, to_date) SELECT ?, grade, rate, from_date,"
                + " to_date FROM rate WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO holiday (sheet_id, holiday_date) SELECT ?, holiday_date FROM holiday"
                + " WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO void_reason (sheet_id, reason) SELECT ?, reason FROM void_reason"
                + " WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO claim_template (sheet_id, name, amount, note) SELECT ?, name, amount, note"
                + " FROM claim_template WHERE sheet_id = ? ORDER BY id", to, from);
        jdbc.update("INSERT INTO claim_tag (sheet_id, tag) SELECT ?, tag FROM claim_tag WHERE sheet_id = ?", to, from);
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) SELECT ?, name, from_date, to_date"
                + " FROM period WHERE sheet_id = ? ORDER BY id", to, from);

        Map<Long, Long> people = new HashMap<>();
        for (Long id : ids("SELECT id FROM person WHERE sheet_id = ? ORDER BY id", from)) {
            long copy = jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO person (sheet_id, name, version,"
                    + " retired_from, terms, contact, list_position, origin) SELECT ?, name, 0, retired_from, terms,"
                    + " contact, list_position, origin FROM person WHERE id = ?)", Long.class, to, id);
            people.put(id, copy);
            jdbc.update("INSERT INTO person_grade (person_id, grade, from_date) SELECT ?, grade, from_date"
                    + " FROM person_grade WHERE person_id = ?", copy, id);
            jdbc.update("INSERT INTO person_hold (person_id, from_date, to_date) SELECT ?, from_date, to_date"
                    + " FROM person_hold WHERE person_id = ? ORDER BY id", copy, id);
            jdbc.update("INSERT INTO person_retirement (person_id, from_date, to_date) SELECT ?, from_date, to_date"
                    + " FROM person_retirement WHERE person_id = ? ORDER BY id", copy, id);
            jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias) SELECT ?, ?, alias FROM person_alias"
                    + " WHERE person_id = ? ORDER BY id", to, copy, id);
        }
        for (Map<String, Object> patron : jdbc.queryForList("SELECT pp.person_id, pp.patron_id FROM person_patron pp"
                + " JOIN person q ON q.id = pp.person_id WHERE q.sheet_id = ? ORDER BY pp.named", from)) {
            Long person = people.get(((Number) patron.get("person_id")).longValue());
            Long named = people.get(((Number) patron.get("patron_id")).longValue());
            if (person != null && named != null) {
                jdbc.update("INSERT INTO person_patron (person_id, patron_id) VALUES (?, ?)", person, named);
            }
        }

        Map<Long, Long> pools = new HashMap<>();
        for (Long id : ids("SELECT id FROM pool WHERE sheet_id = ? ORDER BY id", from)) {
            pools.put(id, jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO pool (sheet_id, name)"
                    + " SELECT ?, name FROM pool WHERE id = ?)", Long.class, to, id));
        }
        for (Map<String, Object> member : jdbc.queryForList("SELECT pool_id, person_id, member_pool_id, share,"
                + " from_date, to_date FROM pool_member WHERE sheet_id = ? ORDER BY id", from)) {
            jdbc.update("INSERT INTO pool_member (sheet_id, pool_id, person_id, member_pool_id, share, from_date,"
                    + " to_date) VALUES (?, ?, ?, ?, ?, ?, ?)", to, pools.get(id(member.get("pool_id"))),
                    people.get(id(member.get("person_id"))), pools.get(id(member.get("member_pool_id"))),
                    member.get("share"), member.get("from_date"), member.get("to_date"));
        }
        return people;
    }

    /**
     * Copy the sheet's claims, each with its log, to the clone's people: a claim that had a number takes its new one
     * from {@code numbers} (by claim id), and a correction or split names its claim by the new number.
     */
    public void copyClaims(String from, String to, Map<Long, Long> people, Map<Long, String> numbers) {
        List<Map<String, Object>> claims = jdbc.queryForList(
                "SELECT id, person_id, claim_number, corrects, split_from FROM claim WHERE sheet_id = ? ORDER BY id", from);
        Map<String, String> renumbered = new HashMap<>();
        for (Map<String, Object> claim : claims) {
            if (claim.get("claim_number") != null) {
                renumbered.put((String) claim.get("claim_number"), numbers.get(id(claim.get("id"))));
            }
        }
        for (Map<String, Object> claim : claims) {
            long id = id(claim.get("id"));
            long copy = jdbc.queryForObject("SELECT id FROM FINAL TABLE (INSERT INTO claim (sheet_id, person_id,"
                    + " amount, claim_date, note, status, claim_number, settled_due, opened_by, stated, stated_due,"
                    + " corrects, listed, deferred_until, proofs, split_from, late_entry, reminded_on, due_from, terms,"
                    + " ref, tags, void_reason, edited_by, due_by, settle_batch)"
                    + " SELECT ?, ?, amount, claim_date, note, status, ?, settled_due, opened_by, FALSE, NULL,"
                    + " ?, listed, deferred_until, proofs, ?, late_entry, reminded_on, due_from, terms,"
                    + " ref, tags, void_reason, edited_by, due_by, NULL FROM claim WHERE id = ?)", Long.class,
                    to, people.get(id(claim.get("person_id"))), numbers.get(id), renumbered.get((String) claim.get("corrects")),
                    renumbered.get((String) claim.get("split_from")), id);
            jdbc.update("INSERT INTO claim_log (sheet_id, claim_id, status, by_user, logged_on, due) SELECT ?, ?,"
                    + " status, by_user, logged_on, due FROM claim_log WHERE claim_id = ? ORDER BY id", to, copy, id);
        }
    }

    private List<Long> ids(String sql, String sheetId) {
        return jdbc.queryForList(sql, Long.class, sheetId);
    }

    private static Long id(Object value) {
        return value == null ? null : ((Number) value).longValue();
    }
}

