        Person found = null;
        try {
            found = repository.find(sheet.id(), Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (found == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        person.set(found);
    }
}
