import { defineSlot } from '../Slot';

/**
 * Extra columns of the people table. A contribution renders one `<th>` in the header slot and one
 * `<td>` per person in the cells slot, at the same order, so the columns line up.
 */
export const PersonHeads = defineSlot<{ sheetId: string; user: string }>('person.heads');
export const PersonCells = defineSlot<{ sheetId: string; user: string; personId: number }>('person.cells');
import { defineSlot } from '../Slot';

/**
 * The body of the screen once a user is signed in and a sheet is loaded. Every per-sheet feature
 * fills it; its context is the active sheet id and the signed-in user.
 */
export const SheetBody = defineSlot<{ sheetId: string; user: string }>('sheet.body');
import type { ComponentType } from 'react';

// The contribution store. It imports NOTHING — that is deliberate: discovery (slots/discover.ts)
// pulls in every feature's contribution file, and those files reach a slot definition, which
// reaches defineSlot, which reaches this file. Keeping the arrows one-way (discover -> features ->
// defs -> Slot -> registry) is what stops the module graph forming a cycle.

export type Registered = {
  slot: string;
  order: number;
  /** Source file — the React key and the deterministic tie-break for equal `order`. */
  from: string;
  Component: ComponentType<never>;
};

const contributions: Registered[] = [];

/** Called once per contribution at startup, by slots/discover.ts. */
export function register(entry: Registered): void {
  contributions.push(entry);
}

export function forSlot(id: string): Registered[] {
  return contributions
    .filter((c) => c.slot === id)
    .sort((a, b) => a.order - b.order || a.from.localeCompare(b.from));
}
import { register } from './registry';
import type { Registered } from './registry';

// Discovery: every `features/**/*.slot.tsx` in the app is found here and registered, so there is
// no explicit list of features. A file exports `contribution`, or `contributions` for more than
// one. Imported once for its side effect by main.tsx.
const modules = import.meta.glob('../features/**/*.slot.tsx', { eager: true }) as Record<
  string,
  { contribution?: Omit<Registered, 'from' | 'order'> & { order?: number }; contributions?: Array<Omit<Registered, 'from' | 'order'> & { order?: number }> }
>;

for (const [from, mod] of Object.entries(modules)) {
  const declared = mod.contributions ?? (mod.contribution ? [mod.contribution] : []);
  for (const c of declared) {
    register({ ...c, from, order: c.order ?? 0 });
  }
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useSubmitOnce } from '../../mutation/useSubmitOnce';
import { useUser } from '../session/useSession';
import { claimsKey } from '../claims/useClaims';

type PasteResult = { added: number };

// The paste box: lines of name,amount,date,note (the note may hold commas; a blank date is the sheet's today;
// the note may be absent) add a DRAFT claim per line, in order, for the named person. The server checks every
// line with the claim form's rules first, so a refusal adds nothing. A note ending " #<reference>" gives the claim
// that reference instead (a reference already on the sheet, or repeated in the paste, refuses it all).
// Shows how many were added; the count is gone while it runs, and shows before the new rows do.
function PasteClaims({ sheetId }: { sheetId: string; user: string }) {
  const [lines, setLines] = useState('');
  const [added, setAdded] = useState<number | null>(null);
  const [user] = useUser();
  const queryClient = useQueryClient();
  const paste = useMutation({
    mutationFn: async (text: string) => {
      setAdded(null);
      if (text.trim() === '') throw new Error('Paste at least one line of name,amount,date,note');
      // `by` is the signed-in user the change is recorded against.
      const result = await postJson<PasteResult>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/paste`, {
        lines: text,
        by: user ?? '',
      });
      setAdded(result.added);
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      return result;
    },
  });

  const submit = useSubmitOnce(paste);
  return (
    <form
      data-testid="paste-box"
      onSubmit={(e) => {
        e.preventDefault();
        submit(lines);
      }}
    >
      <label>
        Paste claims (name,amount,date,note per line)
        <br />
        <textarea
          data-testid="paste-claims"
          rows={4}
          cols={50}
          value={lines}
          onChange={(e) => {
            setLines(e.target.value);
            paste.reset();
          }}
        />
      </label>
      <br />
      <button type="submit" data-testid="paste-submit" disabled={paste.isPending}>
        Add draft claims
      </button>{' '}
      {added !== null && !paste.isError && (
        <span>
          Added <strong data-testid="paste-added">{added}</strong>
        </span>
      )}
      {paste.isError && (
        <p data-testid="paste-error" role="alert">
          {paste.error.message}
        </p>
      )}
    </form>
  );
}

export const contribution = SheetBody.fill({ order: 17, Component: PasteClaims });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A refused request: the reason, and the HTTP status (409: someone else saved the record first). */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

// The date the signed-in user's screen shows the sheet as of (none: as it stands now). Every request carries
// it as `asof`: a read answers as the sheet stood at the end of that date, and a change is refused while it is set.
// It belongs to this screen only, so it is kept here and in the URL (search param `asof`), never in the store.
let viewAsOf = new URLSearchParams(window.location.search).get('asof') ?? '';

export function getViewAsOf(): string {
  return viewAsOf;
}

export function setViewAsOf(date: string): void {
  viewAsOf = date;
}

// Set only while readLive runs its read: the request then goes without the screen's as-of date.
let live = false;

/** Run the read (which must make its request at once) as the sheet stands now, whatever the screen's as-of date. */
export function readLive<T>(read: () => Promise<T>): Promise<T> {
  live = true;
  try {
    return read();
  } finally {
    live = false;
  }
}

async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const asOf = live ? '' : viewAsOf;
  const url = asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asof=${encodeURIComponent(asOf)}`;
  const res = await fetch(url, init);
  if (!res.ok) {
    // A refusal carries {"error": "<why>"}; show that, else the status line.
    const body = (await res.json().catch(() => null)) as { error?: string } | null;
    throw new HttpError(body?.error ?? `${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body?: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}

