  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: move
# The sheet's pools, in the order added, each with its members, total share and whether it is balanced.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: asof
asof:
  class: net.officefloor.hq.app.history.ValidateViewAsOf
  next: respond
